import{_ as t,a,o,a6 as s}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Get Payment Methods","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-payment-methods","title":"Get Available Payment Methods","description":"List the payment methods the store offers for the current cart. Requires the cart token; the list is empty until a checkout address and shipping method are saved.","request":"curl -X GET \\"http://localhost/api/shop/payment-methods\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -H \\"Authorization: Bearer 62f2b3f5-a455-4c78-93ba-eabca63d32ec\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": \\"stripe\\",\\n    \\"method\\": \\"stripe\\",\\n    \\"title\\": \\"Stripe\\",\\n    \\"description\\": \\"Stripe\\",\\n    \\"icon\\": \\"http://localhost/themes/shop/default/build/assets/stripe-WsnmAxt1.png\\",\\n    \\"additionalData\\": null,\\n    \\"isAllowed\\": true\\n  },\\n  {\\n    \\"id\\": \\"cashondelivery\\",\\n    \\"method\\": \\"cashondelivery\\",\\n    \\"title\\": \\"Cash On Delivery\\",\\n    \\"description\\": \\"Cash On Delivery\\",\\n    \\"icon\\": \\"http://localhost/themes/shop/default/build/assets/cash-on-delivery-DUCmTQ0R.png\\",\\n    \\"additionalData\\": null,\\n    \\"isAllowed\\": true\\n  }\\n]\\n","commonErrors":[{"error":"401 Unauthorized","cause":"Missing or invalid `X-STOREFRONT-KEY`","solution":"Send a valid storefront API key."},{"error":"404 Not Found","cause":"No cart resolves from the supplied token","solution":"Create a cart and add an item before reading payment methods."}]}]},"headers":[],"relativePath":"api/rest-api/shop/checkout/get-payment-methods.md","filePath":"api/rest-api/shop/checkout/get-payment-methods.md","lastUpdated":1787725411000}'),d={name:"api/rest-api/shop/checkout/get-payment-methods.md"};function r(i,e,n,h,c,l){return o(),a("div",null,e[0]||(e[0]=[s('<h1 id="get-payment-methods" tabindex="-1">Get Payment Methods <a class="header-anchor" href="#get-payment-methods" aria-label="Permalink to &quot;Get Payment Methods&quot;">​</a></h1><p>List the payment methods available for the current cart.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/payment-methods</span></span></code></pre></div><p>The path is <code>/payment-methods</code>. <code>/api/shop/checkout-payment-methods</code> accepts <strong>POST only</strong> — that is <a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a>, not the read.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td><code>application/json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td><code>Bearer &lt;cartToken&gt;</code> for a guest, or the customer&#39;s Bearer token when signed in</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response Fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response Fields&quot;">​</a></h2><p>The response is a bare array of methods.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Method identifier, the same value as <code>method</code>.</td></tr><tr><td><code>method</code></td><td>string</td><td>Method code — send this to <a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a>.</td></tr><tr><td><code>title</code></td><td>string</td><td>Display name configured by the merchant.</td></tr><tr><td><code>description</code></td><td>string</td><td>Description shown alongside the option.</td></tr><tr><td><code>icon</code></td><td>string</td><td>Absolute URL of the method&#39;s icon.</td></tr><tr><td><code>additionalData</code></td><td>object</td><td>Extra configuration a gateway supplies, or <code>null</code>.</td></tr><tr><td><code>isAllowed</code></td><td>boolean</td><td>Whether the method may be selected for this cart.</td></tr></tbody></table><h2 id="order-of-the-checkout-steps" tabindex="-1">Order of the checkout steps <a class="header-anchor" href="#order-of-the-checkout-steps" aria-label="Permalink to &quot;Order of the checkout steps&quot;">​</a></h2><p>Payment methods depend on the steps before them. Calling this before they are complete returns an empty array rather than an error:</p><ol><li>Save the checkout address with <a href="/api/rest-api/shop/checkout/set-billing-address.html">Set Checkout Address</a>.</li><li>Select a rate with <a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a>.</li><li>Read this list and let the shopper choose.</li></ol><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Render the payment step</strong> — one call gives the title, icon, and code for every option.</li><li><strong>Filter what is selectable</strong> — hide or disable any method whose <code>isAllowed</code> is <code>false</code> rather than letting the shopper pick it and fail at order placement.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Send <code>method</code>, not <code>title</code>, when selecting</strong> — the code is the identifier the set endpoint expects</li><li><strong>Treat an empty array as &quot;steps outstanding&quot;</strong> — it means no address or no shipping method yet, not that the store accepts no payments</li><li><strong>Re-read after changing the address</strong> — availability can differ by country, so a shipping-address change can add or remove methods</li><li><strong>Check <code>isAllowed</code> before rendering</strong> — a method can be listed but blocked for this particular cart</li></ol><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/checkout/set-payment-method.html">Set Payment Method</a> — save the chosen payment method on the cart</li><li><a href="/api/rest-api/shop/checkout/get-shipping-methods.html">Get Shipping Methods</a> — the rates available for the saved address</li><li><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a> — turn the prepared cart into an order</li></ul>',19)]))}const u=t(d,[["render",r]]);export{m as __pageData,u as default};
